<?php
$pageTitle='Agenda'; require_once __DIR__ . '/includes/header.php';
$config=$pdo->query('SELECT * FROM configuracoes WHERE id=1')->fetch();$showCancelled=isset($_GET['canceladas']);$view='mes';$reference=$_GET['data']??date('Y-m-d');$reference=new DateTimeImmutable($reference);
if ($showCancelled) redirect('canceladas.php');
$start=$reference->modify('first day of this month');$end=$reference->modify('last day of this month');$previous=$reference->modify('-1 month');$next=$reference->modify('+1 month');
$monthNames=['01'=>'Janeiro','02'=>'Fevereiro','03'=>'Março','04'=>'Abril','05'=>'Maio','06'=>'Junho','07'=>'Julho','08'=>'Agosto','09'=>'Setembro','10'=>'Outubro','11'=>'Novembro','12'=>'Dezembro'];
$filterMine=isset($_GET['meu']);$filterGroupId=(int)($_GET['grupo_filtro']??0);$filterAreaId=(int)($_GET['area_filtro']??0);
$conditions=['r.data_inicio>=?','r.data_inicio<?'];$params=[$start->format('Y-m-d 00:00:00'),$end->modify('+1 day')->format('Y-m-d 00:00:00')];
if(!$showCancelled){$conditions[]="r.status='ativa'";}
if($filterMine){$conditions[]='r.criado_por=?';$params[]=$_SESSION['usuario_nome']??'';}
if($filterGroupId){$conditions[]='r.grupo_id=?';$params[]=$filterGroupId;}
if($filterAreaId){$conditions[]='r.area_id=?';$params[]=$filterAreaId;}
$sql="SELECT r.*,g.nome grupo,g.cor,COALESCE((SELECT GROUP_CONCAT(sg.nome ORDER BY sg.nome SEPARATOR ', ') FROM subgrupos sg WHERE FIND_IN_SET(sg.id, r.subgrupos_ids)), s.nome) subgrupo,COALESCE(a.nome,'Todas as áreas') area FROM reservas r JOIN grupos g ON g.id=r.grupo_id JOIN subgrupos s ON s.id=r.subgrupo_id LEFT JOIN areas a ON a.id=r.area_id WHERE ".implode(' AND ',$conditions).' ORDER BY r.data_inicio';$s=$pdo->prepare($sql);$s->execute($params);$reservations=$s->fetchAll();$byDay=[];foreach($reservations as $r)$byDay[date('Y-m-d',strtotime($r['data_inicio']))][]=$r;
$filterGroups=$pdo->query("SELECT id,nome FROM grupos ORDER BY nome")->fetchAll();$filterAreas=$pdo->query("SELECT id,nome FROM areas ORDER BY nome")->fetchAll();
$filterActive=$filterMine||$filterGroupId||$filterAreaId;
?><div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Agenda</h1><p class="text-muted mb-0"><?= $view==='mes'?$monthNames[$reference->format('m')].' de '.$reference->format('Y'):$start->format('d/m').' a '.$end->format('d/m/Y') ?></p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="?visao=<?= $view ?>&data=<?= $previous->format('Y-m-d') ?><?= $showCancelled?'&canceladas=1':'' ?>">Anterior</a><a class="btn btn-outline-secondary" href="?visao=<?= $view ?>&data=<?= $next->format('Y-m-d') ?><?= $showCancelled?'&canceladas=1':'' ?>">Próxima</a><button class="btn btn-print" type="button" onclick="window.print()">Imprimir</button></div></div><div class="d-flex flex-wrap justify-content-between align-items-center mb-3 gap-2 no-print"><div class="btn-group"><a class="btn btn-sm btn-outline-secondary" href="agenda.php?data=<?= $reference->format('Y-m-d') ?>">Dia</a><a class="btn btn-sm btn-navy" href="?visao=mes&data=<?= $reference->format('Y-m-d') ?><?= $showCancelled?'&canceladas=1':'' ?>">Mês</a></div><div class="d-flex align-items-center gap-3"><a class="small" href="?visao=<?= $view ?>&data=<?= $reference->format('Y-m-d') ?><?= $showCancelled?'':'&canceladas=1' ?>"><?= $showCancelled?'Ocultar reservas canceladas':'Exibir reservas canceladas' ?></a><button class="btn btn-sm <?= $filterActive?'btn-navy':'btn-outline-secondary' ?>" type="button" data-bs-toggle="collapse" data-bs-target="#filterPanel">Filtro<?= $filterActive?' ●':'' ?></button></div></div><div class="collapse mb-3<?= $filterActive?' show':'' ?> no-print" id="filterPanel"><div class="app-card"><form method="get" class="row g-3 align-items-end"><input type="hidden" name="visao" value="<?= e($view) ?>"><input type="hidden" name="data" value="<?= $reference->format('Y-m-d') ?>"><?php if($showCancelled): ?><input type="hidden" name="canceladas" value="1"><?php endif; ?><div class="col-md-3"><div class="form-check mt-4"><input class="form-check-input" type="checkbox" name="meu" id="meuFiltro" <?= $filterMine?'checked':'' ?>><label class="form-check-label" for="meuFiltro">Somente minhas reservas</label></div></div><div class="col-md-3"><label class="form-label">Grupo</label><select class="form-select" name="grupo_filtro"><option value="">Todos</option><?php foreach($filterGroups as $g): ?><option value="<?= $g['id'] ?>" <?= $filterGroupId===(int)$g['id']?'selected':'' ?>><?= e($g['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Área</label><select class="form-select" name="area_filtro"><option value="">Todas</option><?php foreach($filterAreas as $a): ?><option value="<?= $a['id'] ?>" <?= $filterAreaId===(int)$a['id']?'selected':'' ?>><?= e($a['nome']) ?></option><?php endforeach; ?></select></div><div class="col-md-3 d-flex gap-2"><button class="btn btn-gold" type="submit">Aplicar</button><a class="btn btn-outline-secondary" href="?visao=<?= $view ?>&data=<?= $reference->format('Y-m-d') ?><?= $showCancelled?'&canceladas=1':'' ?>">Limpar</a></div></form></div></div><section class="app-card p-0 overflow-hidden"><div class="month-grid p-2"><?php for($d=$start;$d<=$end;$d=$d->modify('+1 day')):$key=$d->format('Y-m-d');?><div class="month-cell"><span class="month-cell-date"><?= ['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'][(int)$d->format('N')-1] ?> - <?= $d->format('d/m') ?></span><?php foreach($byDay[$key]??[] as $r):?><a class="calendar-event <?= $r['status']==='cancelado'?'cancelled':'' ?>" href="reserva_form.php?id=<?= $r['id'] ?>" style="background-color:<?= e($r['cor']) ?>55" title="<?= e($r['grupo'].' '.$r['subgrupo'].($r['criado_por']?' · Criado por '.$r['criado_por']:'')) ?>"><?= date('H:i',strtotime($r['data_inicio'])) ?> <strong><?= e($r['grupo']) ?></strong><br><?= e($r['subgrupo']) ?> · <?= e($r['area']) ?></a><?php endforeach;?></div><?php endfor;?></div></section><?php require __DIR__.'/includes/footer.php';
